package com.llamaclub;

/**
 * Plugin settings persisted via {@link net.runelite.client.config.ConfigManager}.
 * Not registered as a RuneLite {@link net.runelite.client.config.Config} so the
 * main Configuration panel shows only the plugin on/off toggle (no gear icon).
 */
public interface LlamaClubConfig
{
	String GROUP = "llamaclub";

	boolean webhookEnabled();

	String webhookUrl();

	String pluginToken();

	String websiteUrl();

	int lootMinValue();

	String lootWhitelist();

	boolean lootIncludeUntradeables();

	boolean clueTierBeginner();

	boolean clueTierEasy();

	boolean clueTierMedium();

	boolean clueTierHard();

	boolean clueTierElite();

	boolean clueTierMaster();

	int clueMinValue();

	int clueScreenshotMinValue();

	boolean notifyLoot();

	boolean notifyPet();

	boolean notifyLevel();

	boolean notifyExperience();

	boolean notifyQuest();

	boolean notifyKillCount();

	boolean notifyClue();

	boolean notifyDiary();

	boolean notifyCombatAchievement();

	boolean notifyCollection();

	boolean notifyDeath();

	boolean sendEventScreenshots();

	boolean screenshotIncludeSidebar();

	boolean screenshotHidePrivateMessages();

	String collectionDenylist();

	boolean syncOnLogout();

	boolean displayCodeword();

	String configuredCodeword();

	boolean showCodewordTimestamp();

	String codewordColor();

	String timestampColor();
}

package com.llamaclub;

import com.llamaclub.service.PluginFilterSettingsService;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
class LlamaClubConfigImpl implements LlamaClubConfig
{
	private static final String FIXED_WEBHOOK_URL = "https://llamaclub.co.uk/api/runelite/ingest";
	private static final String FIXED_WEBSITE_URL = "https://llamaclub.co.uk";

	private final ConfigManager configManager;
	private final PluginFilterSettingsService pluginFilterSettingsService;

	@Inject
	LlamaClubConfigImpl(ConfigManager configManager, PluginFilterSettingsService pluginFilterSettingsService)
	{
		this.configManager = configManager;
		this.pluginFilterSettingsService = pluginFilterSettingsService;
	}

	@Override
	public boolean webhookEnabled()
	{
		return true;
	}

	@Override
	public String webhookUrl()
	{
		return FIXED_WEBHOOK_URL;
	}

	@Override
	public String pluginToken()
	{
		return getString("pluginToken", "");
	}

	@Override
	public String websiteUrl()
	{
		return FIXED_WEBSITE_URL;
	}

	@Override
	public int lootMinValue()
	{
		return pluginFilterSettingsService.lootMinValue();
	}

	@Override
	public String lootWhitelist()
	{
		return getString("lootWhitelist", "");
	}

	@Override
	public boolean lootIncludeUntradeables()
	{
		return getBoolean("lootIncludeUntradeables", true);
	}

	@Override
	public boolean clueTierBeginner()
	{
		return getBoolean("clueTierBeginner", true);
	}

	@Override
	public boolean clueTierEasy()
	{
		return getBoolean("clueTierEasy", true);
	}

	@Override
	public boolean clueTierMedium()
	{
		return getBoolean("clueTierMedium", true);
	}

	@Override
	public boolean clueTierHard()
	{
		return getBoolean("clueTierHard", true);
	}

	@Override
	public boolean clueTierElite()
	{
		return getBoolean("clueTierElite", true);
	}

	@Override
	public boolean clueTierMaster()
	{
		return getBoolean("clueTierMaster", true);
	}

	@Override
	public int clueMinValue()
	{
		return pluginFilterSettingsService.clueMinValue();
	}

	@Override
	public int clueScreenshotMinValue()
	{
		return pluginFilterSettingsService.clueScreenshotMinValue();
	}

	@Override
	public boolean notifyLoot()
	{
		return getBoolean("notifyLoot", true);
	}

	@Override
	public boolean notifyPet()
	{
		return getBoolean("notifyPet", true);
	}

	@Override
	public boolean notifyLevel()
	{
		return getBoolean("notifyLevel", true);
	}

	@Override
	public boolean notifyExperience()
	{
		return getBoolean("notifyExperience", true);
	}

	@Override
	public boolean notifyQuest()
	{
		return getBoolean("notifyQuest", true);
	}

	@Override
	public boolean notifyKillCount()
	{
		return getBoolean("notifyKillCount", true);
	}

	@Override
	public boolean notifyClue()
	{
		return getBoolean("notifyClue", true);
	}

	@Override
	public boolean notifyDiary()
	{
		return getBoolean("notifyDiary", true);
	}

	@Override
	public boolean notifyCombatAchievement()
	{
		return getBoolean("notifyCombatAchievement", true);
	}

	@Override
	public boolean notifyCollection()
	{
		return getBoolean("notifyCollection", true);
	}

	@Override
	public boolean notifyDeath()
	{
		return getBoolean("notifyDeath", true);
	}

	@Override
	public boolean sendEventScreenshots()
	{
		return true;
	}

	@Override
	public boolean screenshotIncludeSidebar()
	{
		return getBoolean("screenshotIncludeSidebar", true);
	}

	@Override
	public boolean screenshotHidePrivateMessages()
	{
		return getBoolean("screenshotHidePrivateMessages", false);
	}

	@Override
	public String collectionDenylist()
	{
		return getString("collectionDenylist", "");
	}

	@Override
	public boolean syncOnLogout()
	{
		return true;
	}

	@Override
	public boolean displayCodeword()
	{
		return getBoolean("displayCodeword", false);
	}

	@Override
	public String configuredCodeword()
	{
		return getString("configuredCodeword", "");
	}

	@Override
	public boolean showCodewordTimestamp()
	{
		return getBoolean("showCodewordTimestamp", true);
	}

	@Override
	public String codewordColor()
	{
		return getString("codewordColor", "#FD8F00");
	}

	@Override
	public String timestampColor()
	{
		return getString("timestampColor", "#FF9A00");
	}

	private boolean getBoolean(String key, boolean defaultValue)
	{
		String value = configManager.getConfiguration(GROUP, key);
		return value != null ? Boolean.parseBoolean(value) : defaultValue;
	}

	private int getInt(String key, int defaultValue)
	{
		String value = configManager.getConfiguration(GROUP, key);
		if (value == null)
		{
			return defaultValue;
		}
		try
		{
			return Integer.parseInt(value);
		}
		catch (NumberFormatException e)
		{
			return defaultValue;
		}
	}

	private String getString(String key, String defaultValue)
	{
		String value = configManager.getConfiguration(GROUP, key);
		return value != null ? value : defaultValue;
	}
}

package com.llamaclub;

import com.google.inject.Binder;
import com.google.inject.Singleton;
import com.llamaclub.api.WebhookClient;
import com.llamaclub.auth.AccountIdentity;
import com.llamaclub.combat.BarrowsBrotherCombatTracker;
import com.llamaclub.combat.LunarMoonCombatTracker;
import com.llamaclub.combat.BossFightTracker;
import com.llamaclub.combat.SpecAttributionService;
import com.llamaclub.events.ClueNotifier;
import com.llamaclub.events.CollectionLogNotifier;
import com.llamaclub.events.CombatAchievementNotifier;
import com.llamaclub.events.DeathNotifier;
import com.llamaclub.events.DiaryNotifier;
import com.llamaclub.events.KillCountNotifier;
import com.llamaclub.events.LevelNotifier;
import com.llamaclub.events.LootNotifier;
import com.llamaclub.events.PetNotifier;
import com.llamaclub.events.QuestNotifier;
import com.llamaclub.loot.RecentLootTracker;
import com.llamaclub.service.SyncService;
import com.llamaclub.sync.CombatAchievementBossWidgetListener;
import com.llamaclub.ui.CodeWordOverlay;
import com.llamaclub.ui.LlamaClubPanel;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.api.events.GameTick;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Llama Club",
	description = "Sync player data and send clan notifications to llamaclub.co.uk",
	tags = {"clan", "llama", "llamaclub", "webhook"}
)
public class LlamaClubPlugin extends Plugin
{
	@Inject
	private EventBus eventBus;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private LlamaClubConfig config;

	@Inject
	private LlamaClubPanel panel;

	@Inject
	private SyncService syncService;

	@Inject
	private WebhookClient webhookClient;

	@Inject
	private LootNotifier lootNotifier;

	@Inject
	private PetNotifier petNotifier;

	@Inject
	private LevelNotifier levelNotifier;

	@Inject
	private QuestNotifier questNotifier;

	@Inject
	private KillCountNotifier killCountNotifier;

	@Inject
	private BarrowsBrotherCombatTracker barrowsBrotherCombatTracker;

	@Inject
	private LunarMoonCombatTracker lunarMoonCombatTracker;

	@Inject
	private BossFightTracker bossFightTracker;

	@Inject
	private SpecAttributionService specAttributionService;

	@Inject
	private ClueNotifier clueNotifier;

	@Inject
	private DiaryNotifier diaryNotifier;

	@Inject
	private CombatAchievementNotifier combatAchievementNotifier;

	@Inject
	private CollectionLogNotifier collectionLogNotifier;

	@Inject
	private DeathNotifier deathNotifier;

	@Inject
	private RecentLootTracker recentLootTracker;

	@Inject
	private ClientThread clientThread;

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private CodeWordOverlay codeWordOverlay;

	@Inject
	private AccountIdentity accountIdentity;

	@Inject
	private CombatAchievementBossWidgetListener combatAchievementBossWidgetListener;

	private NavigationButton navButton;
	private GameState previousGameState;
	private int adminCheckTickCounter;
	private volatile boolean sessionEndSyncDispatched;

	@Override
	public void configure(Binder binder)
	{
		binder.bind(LlamaClubConfig.class).to(LlamaClubConfigImpl.class).in(Singleton.class);
	}

	@Override
	protected void startUp()
	{
		BufferedImage icon = loadIcon();

		navButton = NavigationButton.builder()
			.tooltip("Llama Club")
			.icon(icon)
			.priority(5)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		overlayManager.add(codeWordOverlay);
		registerNotifiers();
		levelNotifier.resetSession();
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			levelNotifier.beginLoginHydration();
		}
		previousGameState = client.getGameState();
		sessionEndSyncDispatched = false;
		panel.reloadPersistedLastSyncAt();
		panel.refreshStatus();
		panel.refreshAdminAccess();
		adminCheckTickCounter = 0;
		log.info("Llama Club plugin started");
	}

	@Override
	protected void shutDown()
	{
		if (config.syncOnLogout() && !sessionEndSyncDispatched)
		{
			sessionEndSyncDispatched = true;
			syncService.syncOnSessionEnd(success ->
			{
				if (success)
				{
					panel.recordSuccessfulSync();
				}
			});
		}

		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		unregisterNotifiers();
		levelNotifier.resetSession();
		overlayManager.remove(codeWordOverlay);
		log.info("Llama Club plugin stopped");
	}

	private void registerNotifiers()
	{
		eventBus.register(lootNotifier);
		eventBus.register(petNotifier);
		eventBus.register(levelNotifier);
		eventBus.register(questNotifier);
		eventBus.register(killCountNotifier);
		eventBus.register(barrowsBrotherCombatTracker);
		eventBus.register(lunarMoonCombatTracker);
		eventBus.register(bossFightTracker);
		eventBus.register(specAttributionService);
		eventBus.register(clueNotifier);
		eventBus.register(diaryNotifier);
		eventBus.register(combatAchievementNotifier);
		eventBus.register(collectionLogNotifier);
		eventBus.register(deathNotifier);
		eventBus.register(recentLootTracker);
		eventBus.register(combatAchievementBossWidgetListener);
	}

	private void unregisterNotifiers()
	{
		eventBus.unregister(lootNotifier);
		eventBus.unregister(petNotifier);
		eventBus.unregister(levelNotifier);
		eventBus.unregister(questNotifier);
		eventBus.unregister(killCountNotifier);
		eventBus.unregister(barrowsBrotherCombatTracker);
		eventBus.unregister(lunarMoonCombatTracker);
		eventBus.unregister(bossFightTracker);
		eventBus.unregister(specAttributionService);
		eventBus.unregister(clueNotifier);
		eventBus.unregister(diaryNotifier);
		eventBus.unregister(combatAchievementNotifier);
		eventBus.unregister(collectionLogNotifier);
		eventBus.unregister(deathNotifier);
		eventBus.unregister(recentLootTracker);
		eventBus.unregister(combatAchievementBossWidgetListener);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState newState = event.getGameState();

		if (GameSessionStates.shouldEndPlaySession(previousGameState, newState))
		{
			levelNotifier.flushPendingExperience();
		}

		if (config.syncOnLogout() && GameSessionStates.shouldEndPlaySession(previousGameState, newState)
			&& !sessionEndSyncDispatched)
		{
			sessionEndSyncDispatched = true;
			syncService.syncOnSessionEnd(success ->
			{
				if (success)
				{
					panel.recordSuccessfulSync();
				}
				else
				{
					log.debug("Logout sync did not complete successfully");
				}
			});
		}

		if (newState == GameState.LOGGED_IN)
		{
			sessionEndSyncDispatched = false;
			panel.reloadPersistedLastSyncAt();
			adminCheckTickCounter = 0;
			panel.refreshAdminAccess();
			webhookClient.fetchBingoLootWhitelistAsync();
			webhookClient.fetchPluginFilterSettingsAsync();
		}

		previousGameState = newState;
		panel.refreshStatus();
	}

	@Subscribe
	public void onGameTick(GameTick gameTick)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		accountIdentity.refreshCachedUsername();

		if (adminCheckTickCounter < 10)
		{
			adminCheckTickCounter++;
			if (adminCheckTickCounter == 5 || adminCheckTickCounter == 10)
			{
				panel.refreshAdminAccess();
			}
		}
	}

	private BufferedImage loadIcon()
	{
		try
		{
			return ImageUtil.loadImageResource(getClass(), "llama_icon.png");
		}
		catch (IllegalArgumentException e)
		{
			log.warn("Missing llama_icon.png, using default sidebar icon");
			return createDefaultIcon();
		}
	}

	private static BufferedImage createDefaultIcon()
	{
		BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = icon.createGraphics();
		graphics.setColor(new Color(183, 142, 66));
		graphics.fillOval(2, 2, 12, 12);
		graphics.dispose();
		return icon;
	}
}

package com.llamaclub.api;

import com.llamaclub.auth.AccountIdentity;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
public class PayloadBuilder
{
	@Inject
	private AccountIdentity accountIdentity;

	public Map<String, Object> buildEvent(String kind, Map<String, Object> eventData)
	{
		Map<String, Object> payload = basePayload("event");
		payload.put("event", event(eventData, kind));
		return payload;
	}

	public Map<String, Object> buildPlayerSync(Map<String, Object> playerSync)
	{
		Map<String, Object> payload = basePayload("player_sync");
		payload.put("playerSync", playerSync);
		return payload;
	}

	public Map<String, Object> buildClanSync(Map<String, Object> clanSync)
	{
		Map<String, Object> payload = basePayload("clan_sync");
		payload.put("clanSync", clanSync);
		return payload;
	}

	private Map<String, Object> basePayload(String type)
	{
		Map<String, Object> payload = new HashMap<>();
		payload.put("schemaVersion", 1);
		payload.put("type", type);
		payload.put("sentAt", System.currentTimeMillis());
		payload.put("identity", accountIdentity.build());
		return payload;
	}

	private static Map<String, Object> event(Map<String, Object> eventData, String kind)
	{
		Map<String, Object> event = new HashMap<>(eventData);
		event.put("kind", kind);
		return event;
	}
}

