import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.llamaclub.LlamaClubConfig;
import com.llamaclub.service.BingoLootWhitelistService;
import com.llamaclub.service.PluginFilterSettingsService;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.lang.reflect.Type;
import java.util.Base64;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import java.util.zip.GZIPOutputStream;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.MultipartBody;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

@Slf4j
@Singleton
public class WebhookClient
{
	public static final String PLUGIN_VERSION = "1.0.0";
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final MediaType PNG = MediaType.parse("image/png");
	private static final Type MAP_TYPE = new TypeToken<Map<String, Object>>() {}.getType();

	private final OkHttpClient httpClient;

	@Inject
	private Gson gson;

	@Inject
	private LlamaClubConfig config;

	@Inject
	private BingoLootWhitelistService bingoLootWhitelistService;

	@Inject
	private PluginFilterSettingsService pluginFilterSettingsService;

	@Inject
	public WebhookClient(OkHttpClient okHttpClient, Gson gson)
	{
		this.gson = gson;
		this.httpClient = okHttpClient.newBuilder()
			.followRedirects(false)
			.followSslRedirects(false)
			.build();
	}

	public void sendMultipartAsync(
		String url,
		Map<String, Object> payload,
		byte[] screenshotPng,
		Consumer<Boolean> callback
	)
	{
		String webhookUrl = normalizeWebhookUrl(url);
		if (webhookUrl == null || webhookUrl.isEmpty())
		{
			if (callback != null)
			{
				callback.accept(false);
			}
			return;
		}

		if (screenshotPng == null || screenshotPng.length == 0)
		{
			sendAsync(url, payload, callback);
			return;
		}

		try
		{
			MultipartBody body = new MultipartBody.Builder()
				.setType(MultipartBody.FORM)
				.addFormDataPart("payload", gson.toJson(payload))
				.addFormDataPart("screenshot", "screenshot.png", RequestBody.create(PNG, screenshotPng))
				.build();

			Request.Builder requestBuilder = new Request.Builder()
				.url(webhookUrl)
				.post(body)
				.addHeader("Accept", "application/json")
				.addHeader("User-Agent", "RuneLite-LlamaClub-Plugin/" + PLUGIN_VERSION);

			applyAuthHeader(requestBuilder, payload);
			enqueueBooleanRequest(
				requestBuilder.build(),
				webhookUrl,
				callback == null ? null : (success, error) -> callback.accept(success)
			);
		}
		catch (RuntimeException e)
		{
			log.warn("Failed to prepare multipart webhook payload: {}", e.getMessage());
			if (callback != null)
			{
				callback.accept(false);
			}
		}
	}

	public void sendAsync(String url, Map<String, Object> payload, Consumer<Boolean> callback)
	{
		sendAsync(url, payload, callback == null ? null : (success, error) -> callback.accept(success));
	}

	public void sendAsync(String url, Map<String, Object> payload, BiConsumer<Boolean, String> callback)
	{
		String webhookUrl = normalizeWebhookUrl(url);
		if (webhookUrl == null || webhookUrl.isEmpty())
		{
			if (callback != null)
			{
				callback.accept(false, "Webhook URL is not configured");
			}
			return;
		}

		if (url != null && !webhookUrl.equals(url.trim()))
		{
			log.warn("Webhook URL pointed at token endpoint; using ingest URL instead: {}", webhookUrl);
		}

		try
		{
			Request request = buildGzipJsonRequest(webhookUrl, payload);
			enqueueBooleanRequest(request, webhookUrl, callback);
		}
		catch (IOException e)
		{
			log.warn("Failed to prepare webhook payload: {}", e.getMessage());
			if (callback != null)
			{
				callback.accept(false, "Failed to prepare sync payload");
			}
		}
	}

	public void fetchBingoLootWhitelistAsync()
	{
		if (!config.webhookEnabled())
		{
			return;
		}

		String token = config.pluginToken();
		if (token == null || token.isBlank())
		{
			return;
		}

		String whitelistUrl = bingoLootWhitelistUrl(config.webhookUrl());
		if (whitelistUrl == null || whitelistUrl.isEmpty())
		{
			return;
		}

		Request request = new Request.Builder()
			.url(whitelistUrl)
			.get()
			.addHeader("Accept", "application/json")
			.addHeader("Authorization", "Bearer " + token.trim())
			.addHeader("User-Agent", "RuneLite-LlamaClub-Plugin/" + PLUGIN_VERSION)
			.build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Bingo loot whitelist fetch failed: {}", e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				String responseBody = readBody(response);
				if (response.isSuccessful())
				{
					bingoLootWhitelistService.updateFromResponseBody(responseBody);
				}
				response.close();
			}
		});
	}

	public void fetchPluginFilterSettingsAsync()
	{
		if (!config.webhookEnabled())
		{
			return;
		}

		String token = config.pluginToken();
		if (token == null || token.isBlank())
		{
			return;
		}

		String settingsUrl = pluginFilterSettingsUrl(config.webhookUrl());
		if (settingsUrl == null || settingsUrl.isEmpty())
		{
			return;
		}

		Request request = new Request.Builder()
			.url(settingsUrl)
			.get()
			.addHeader("Accept", "application/json")
			.addHeader("Authorization", "Bearer " + token.trim())
			.addHeader("User-Agent", "RuneLite-LlamaClub-Plugin/" + PLUGIN_VERSION)
			.build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Plugin filter settings fetch failed: {}", e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				String responseBody = readBody(response);
				if (response.isSuccessful())
				{
					pluginFilterSettingsService.updateFromResponseBody(responseBody);
				}
				response.close();
			}
		});
	}

	/**
	 * Sends an event payload immediately and returns the recorded event id (null on failure).
	 */
	public void sendEventAsync(String url, Map<String, Object> payload, Consumer<Long> callback)
	{
		String webhookUrl = normalizeWebhookUrl(url);
		if (webhookUrl == null || webhookUrl.isEmpty())
		{
			if (callback != null)
			{
				callback.accept(null);
			}
			return;
		}

		try
		{
			Request request = buildGzipJsonRequest(webhookUrl, payload);
			enqueueEventRequest(request, webhookUrl, callback);
		}
		catch (IOException e)
		{
			log.warn("Failed to prepare event payload: {}", e.getMessage());
			if (callback != null)
			{
				callback.accept(null);
			}
		}
	}

	/**
	 * Attaches a screenshot to a previously recorded event via gzip JSON (same transport as ingest).
	 */
	public void uploadEventScreenshotAsync(
		String ingestUrl,
		long eventId,
		String bearerToken,
		String format,
		byte[] imageBytes,
		Consumer<Boolean> callback
	)
	{
		String uploadUrl = eventScreenshotUrl(ingestUrl, eventId);
		String authToken = resolveBearerToken(null);
		if (authToken == null)
		{
			authToken = bearerToken != null ? bearerToken.trim() : null;
		}
		if (uploadUrl == null || uploadUrl.isEmpty()
			|| authToken == null || authToken.isBlank()
			|| format == null || format.isBlank()
			|| imageBytes == null || imageBytes.length == 0)
		{
			if (callback != null)
			{
				callback.accept(false);
			}
			return;
		}

		try
		{
			Map<String, Object> payload = new HashMap<>();
			payload.put("format", format);
			payload.put("data", Base64.getEncoder().encodeToString(imageBytes));

			byte[] body = compressJson(gson.toJson(payload));
			Request request = new Request.Builder()
				.url(uploadUrl)
				.post(RequestBody.create(JSON, body))
				.addHeader("Accept", "application/json")
				.addHeader("Content-Type", "application/json")
				.addHeader("Content-Encoding", "gzip")
				.addHeader("Authorization", "Bearer " + authToken)
				.addHeader("User-Agent", "RuneLite-LlamaClub-Plugin/" + PLUGIN_VERSION)
				.build();

			enqueueScreenshotRequest(request, uploadUrl, callback);
		}
		catch (IOException e)
		{
			log.warn("Failed to prepare screenshot upload: {}", e.getMessage());
			if (callback != null)
			{
				callback.accept(false);
			}
		}
	}

	private Request buildGzipJsonRequest(String webhookUrl, Map<String, Object> payload) throws IOException
	{
		byte[] body = compressJson(gson.toJson(payload));
		Request.Builder requestBuilder = new Request.Builder()
			.url(webhookUrl)
			.post(RequestBody.create(JSON, body))
			.addHeader("Accept", "application/json")
			.addHeader("Content-Type", "application/json")
			.addHeader("Content-Encoding", "gzip")
			.addHeader("User-Agent", "RuneLite-LlamaClub-Plugin/" + PLUGIN_VERSION);

		applyAuthHeader(requestBuilder, payload);
		return requestBuilder.build();
	}

	private void applyAuthHeader(Request.Builder requestBuilder, Map<String, Object> payload)
	{
		String token = resolveBearerToken(payload);
		if (token != null)
		{
			requestBuilder.addHeader("Authorization", "Bearer " + token);
		}
	}

	private String resolveBearerToken(Map<String, Object> payload)
	{
		String configured = config.pluginToken();
		if (configured != null)
		{
			configured = configured.trim();
			if (!configured.isEmpty())
			{
				return configured;
			}
		}

		if (payload == null)
		{
			return null;
		}

		Object identity = payload.get("identity");
		if (identity instanceof Map)
		{
			Object token = ((Map<?, ?>) identity).get("pluginToken");
			if (token instanceof String && !((String) token).isBlank())
			{
				return ((String) token).trim();
			}
		}

		return null;
	}

	private void enqueueBooleanRequest(Request request, String webhookUrl, BiConsumer<Boolean, String> callback)
	{
		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("Webhook request failed: {}", e.getMessage());
				if (callback != null)
				{
					callback.accept(false, "Could not reach the website — check the webhook URL");
				}
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				String responseBody = readBody(response);
				boolean success = isSuccessfulIngestResponse(response, responseBody);
				if (!success)
				{
					logWebhookFailure(response, webhookUrl, responseBody);
				}
				else
				{
					logIngestSuccess(responseBody);
					bingoLootWhitelistService.updateFromResponseBody(responseBody);
					pluginFilterSettingsService.updateFromResponseBody(responseBody);
				}
				response.close();
				if (callback != null)
				{
					callback.accept(success, success ? null : describeIngestFailure(response.code(), responseBody));
				}
			}
		});
	}

	private void enqueueEventRequest(Request request, String webhookUrl, Consumer<Long> callback)
	{
		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("Event webhook request failed: {}", e.getMessage());
				if (callback != null)
				{
					callback.accept(null);
				}
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				String responseBody = readBody(response);
				Long eventId = parseRecordedEventId(response, responseBody);
				if (eventId == null)
				{
					logWebhookFailure(response, webhookUrl, responseBody);
				}
				else
				{
					bingoLootWhitelistService.updateFromResponseBody(responseBody);
					pluginFilterSettingsService.updateFromResponseBody(responseBody);
				}
				response.close();
				if (callback != null)
				{
					callback.accept(eventId);
				}
			}
		});
	}

	private void enqueueScreenshotRequest(Request request, String uploadUrl, Consumer<Boolean> callback)
	{
		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("Screenshot upload failed: {}", e.getMessage());
				if (callback != null)
				{
					callback.accept(false);
				}
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				String responseBody = readBody(response);
				boolean success = isSuccessfulScreenshotResponse(response, responseBody);
				if (!success)
				{
					log.warn("Screenshot upload returned HTTP {} for {}: {}",
						response.code(), uploadUrl, responseBody);
				}
				response.close();
				if (callback != null)
				{
					callback.accept(success);
				}
			}
		});
	}

	private void logWebhookFailure(Response response, String webhookUrl, String responseBody)
	{
		log.warn("Webhook returned HTTP {} for {}: {}", response.code(), webhookUrl, responseBody);
		if (webhookUrl.contains("/tokens"))
		{
			log.warn("Use /api/runelite/ingest for sync and events, not /api/runelite/tokens");
		}
	}

	private void logIngestSuccess(String responseBody)
	{
		if (responseBody == null || responseBody.isBlank())
		{
			return;
		}

		try
		{
			Map<String, Object> parsed = gson.fromJson(responseBody, MAP_TYPE);
			Object status = parsed.get("status");
			if (!"roster_synced".equals(status))
			{
				return;
			}

			log.info(
				"Clan roster stored on server: memberCount={}, joinDateCount={}",
				parsed.get("memberCount"),
				parsed.get("joinDateCount")
			);
		}
		catch (RuntimeException ignored)
		{
			// Response body may not be JSON
		}
	}

	private static String readBody(Response response)
	{
		try
		{
			if (response.body() != null)
			{
				return response.body().string();
			}
		}
		catch (IOException ignored)
		{
			// Response body may be unavailable
		}

		return "";
	}

	private Long parseRecordedEventId(Response response, String responseBody)
	{
		if (!isSuccessfulIngestResponse(response, responseBody))
		{
			return null;
		}

		try
		{
			Map<String, Object> parsed = gson.fromJson(responseBody, MAP_TYPE);
			return parseEventId(parsed.get("eventId"));
		}
		catch (RuntimeException e)
		{
			log.warn("Event response did not include a valid eventId");
			return null;
		}
	}

	private static Long parseEventId(Object eventId)
	{
		if (eventId instanceof Number)
		{
			return ((Number) eventId).longValue();
		}

		if (eventId instanceof String)
		{
			try
			{
				return Long.parseLong((String) eventId);
			}
			catch (NumberFormatException ignored)
			{
				return null;
			}
		}

		return null;
	}

	private boolean isSuccessfulIngestResponse(Response response, String responseBody)
	{
		if (response.code() >= 300 && response.code() < 400)
		{
			return false;
		}

		if (!response.isSuccessful())
		{
			return false;
		}

		if (responseBody == null || responseBody.isBlank())
		{
			return false;
		}

		try
		{
			Map<String, Object> parsed = gson.fromJson(responseBody, MAP_TYPE);
			Object status = parsed.get("status");
			return "synced".equals(status) || "recorded".equals(status) || "roster_synced".equals(status);
		}
		catch (RuntimeException e)
		{
			log.warn("Webhook response was not valid ingest JSON");
			return false;
		}
	}

	private String describeIngestFailure(int statusCode, String responseBody)
	{
		return WebhookClientErrorMessages.describeFailure(gson, statusCode, responseBody);
	}

	private boolean isSuccessfulScreenshotResponse(Response response, String responseBody)
	{
		if (!response.isSuccessful() || responseBody == null || responseBody.isBlank())
		{
			return false;
		}

		try
		{
			Map<String, Object> parsed = gson.fromJson(responseBody, MAP_TYPE);
			return "screenshot_attached".equals(parsed.get("status"));
		}
		catch (RuntimeException e)
		{
			return false;
		}
	}

	private static byte[] compressJson(String json) throws IOException
	{
		byte[] jsonBytes = json.getBytes("UTF-8");
		ByteArrayOutputStream byteStream = new ByteArrayOutputStream();
		try (GZIPOutputStream gzipStream = new GZIPOutputStream(byteStream))
		{
			gzipStream.write(jsonBytes);
		}
		return byteStream.toByteArray();
	}

	static String normalizeWebhookUrl(String url)
	{
		if (url == null)
		{
			return null;
		}

		String trimmed = url.trim();
		if (trimmed.isEmpty())
		{
			return trimmed;
		}

		if (trimmed.contains("/api/runelite/tokens"))
		{
			return trimmed.replace("/api/runelite/tokens", "/api/runelite/ingest");
		}

		return trimmed;
	}

	static String bingoLootWhitelistUrl(String ingestUrl)
	{
		String normalized = normalizeWebhookUrl(ingestUrl);
		if (normalized == null || normalized.isEmpty())
		{
			return null;
		}

		if (normalized.endsWith("/ingest"))
		{
			return normalized.substring(0, normalized.length() - "/ingest".length())
				+ "/bingo/loot-whitelist";
		}

		return normalized + "/bingo/loot-whitelist";
	}

	static String pluginFilterSettingsUrl(String ingestUrl)
	{
		String normalized = normalizeWebhookUrl(ingestUrl);
		if (normalized == null || normalized.isEmpty())
		{
			return null;
		}

		if (normalized.endsWith("/ingest"))
		{
			return normalized.substring(0, normalized.length() - "/ingest".length())
				+ "/plugin-filter-settings";
		}

		return normalized + "/plugin-filter-settings";
	}

	static String eventScreenshotUrl(String ingestUrl, long eventId)
	{
		String normalized = normalizeWebhookUrl(ingestUrl);
		if (normalized == null || normalized.isEmpty())
		{
			return null;
		}

		if (normalized.endsWith("/ingest"))
		{
			return normalized.substring(0, normalized.length() - "/ingest".length())
				+ "/events/" + eventId + "/screenshot";
		}

		return normalized + "/events/" + eventId + "/screenshot";
	}
}

package com.llamaclub.api;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.List;
import java.util.Map;
import java.util.Set;

final class WebhookClientErrorMessages
{
	private static final Type MAP_TYPE = new TypeToken<Map<String, Object>>() {}.getType();
	private static final Set<String> GENERIC_ERROR_MESSAGES = Set.of(
		"Ingest rejected.",
		"Screenshot attachment rejected.",
		"Server Error",
		"Ingest failed due to a server error."
	);

	private WebhookClientErrorMessages()
	{
	}

	static String describeFailure(Gson gson, int statusCode, String responseBody)
	{
		if (statusCode >= 300 && statusCode < 400)
		{
			return "Webhook request was redirected — use /api/runelite/ingest";
		}

		if (statusCode == 401)
		{
			return "Invalid plugin token — generate a new one on the website";
		}

		if (statusCode == 503)
		{
			return "RuneLite ingest is disabled on the server";
		}

		if (statusCode == 404)
		{
			return "API endpoint not found — the RuneLite backend may not be deployed to this URL yet";
		}

		if (statusCode == 429)
		{
			return "Too many requests — wait a minute and try again";
		}

		if (statusCode >= 500)
		{
			String fromBody = extractFirstErrorMessage(gson, responseBody);
			if (fromBody != null && !GENERIC_ERROR_MESSAGES.contains(fromBody))
			{
				return fromBody;
			}

			return "Website server error during ingest — contact a clan admin";
		}

		String fromBody = extractFirstErrorMessage(gson, responseBody);
		if (fromBody != null)
		{
			return fromBody;
		}

		if (statusCode == 403)
		{
			return "Player is not a clan member — sync while logged into a clan character";
		}

		return "Sync failed (HTTP " + statusCode + ")";
	}

	private static String extractFirstErrorMessage(Gson gson, String responseBody)
	{
		if (responseBody == null || responseBody.isBlank())
		{
			return null;
		}

		try
		{
			Map<String, Object> parsed = gson.fromJson(responseBody, MAP_TYPE);
			String fromErrors = extractFirstValidationError(parsed.get("errors"));
			if (fromErrors != null)
			{
				return fromErrors;
			}

			Object message = parsed.get("message");
			if (message instanceof String && !((String) message).isBlank())
			{
				String text = (String) message;
				if (!GENERIC_ERROR_MESSAGES.contains(text))
				{
					return text;
				}
			}
		}
		catch (RuntimeException ignored)
		{
			// Response body may not be JSON
		}

		return null;
	}

	private static String extractFirstValidationError(Object errors)
	{
		if (!(errors instanceof Map))
		{
			return null;
		}

		for (Object value : ((Map<?, ?>) errors).values())
		{
			if (value instanceof List && !((List<?>) value).isEmpty())
			{
				Object first = ((List<?>) value).get(0);
				if (first instanceof String && !((String) first).isBlank())
				{
					return (String) first;
				}
			}
		}

		return null;
	}
}

package com.llamaclub.auth;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneScapeProfileType;
import net.runelite.client.util.Text;

@Singleton
public class AccountIdentity
{
	@Inject
	private Client client;

	@Inject
	private ConfigManager configManager;

	@Inject
	private com.llamaclub.LlamaClubConfig config;

	private String cachedUsername;

	/**
	 * Keeps the last known in-game name available for logout sync.
	 */
	public void refreshCachedUsername()
	{
		resolveUsername();
	}

	public Map<String, Object> build()
	{
		Map<String, Object> identity = new HashMap<>();
		identity.put("pluginToken", config.pluginToken());
		identity.put("accountHash", Long.toString(client.getAccountHash()));
		identity.put("rsProfileKey", configManager.getRSProfileKey());
		identity.put("world", client.getWorld());

		String username = resolveUsername();
		if (username != null)
		{
			identity.put("username", username);
		}

		if (configManager.getProfile() != null)
		{
			identity.put("runeliteProfileId", Long.toString(configManager.getProfile().getId()));
		}

		RuneScapeProfileType profileType = RuneScapeProfileType.getCurrent(client);
		if (profileType != null)
		{
			identity.put("profileType", profileType.name());
		}

		return identity;
	}

	private String resolveUsername()
	{
		Player local = client.getLocalPlayer();
		if (local != null && local.getName() != null && !local.getName().isBlank())
		{
			cachedUsername = normalizeUsername(local.getName());
			return cachedUsername;
		}

		if (cachedUsername != null && !cachedUsername.isBlank())
		{
			return cachedUsername;
		}

		String profileDisplayName = configManager.getRSProfileConfiguration(
			ConfigManager.RSPROFILE_GROUP,
			ConfigManager.RSPROFILE_DISPLAY_NAME
		);
		if (profileDisplayName != null && !profileDisplayName.isBlank())
		{
			cachedUsername = normalizeUsername(profileDisplayName);
			return cachedUsername;
		}

		return null;
	}

	static String normalizeUsername(String username)
	{
		if (username == null || username.isBlank())
		{
			return null;
		}

		return Text.toJagexName(username);
	}
}

package com.llamaclub.clan;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanMember;
import net.runelite.api.clan.ClanRank;
import net.runelite.api.clan.ClanSettings;
import net.runelite.client.util.Text;

@Singleton
public class ClanAdminService
{
	private static final ClanRank DEPUTY_OWNER = ClanRank.DEPUTY_OWNER;

	@Inject
	private Client client;

	public boolean canAccessAdmin()
	{
		ClanSettings clanSettings = client.getClanSettings();
		Player local = client.getLocalPlayer();
		if (clanSettings == null || local == null)
		{
			return false;
		}

		ClanMember member = clanSettings.findMember(local.getName());
		if (member == null)
		{
			member = clanSettings.findMember(Text.toJagexName(local.getName()));
		}
		if (member == null)
		{
			return false;
		}

		ClanRank rank = member.getRank();
		return rank.equals(ClanRank.OWNER) || rank.equals(DEPUTY_OWNER);
	}
}

package com.llamaclub.clan;

import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.clan.ClanMember;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

@Slf4j
@Singleton
public class ClanJoinDateScraper
{
	private static final int RSN_COLUMN = 10;
	private static final int FIRST_COLUMN = 11;
	private static final int SECOND_COLUMN = 13;
	private static final int FIRST_DROPDOWN = 7;
	private static final int SECOND_DROPDOWN = 8;

	private static final DateTimeFormatter UI_DATE_SHORT = DateTimeFormatter.ofPattern("d-MMM-yyyy", Locale.ENGLISH);
	private static final DateTimeFormatter UI_DATE_LONG = DateTimeFormatter.ofPattern("d-MMMM-yyyy", Locale.ENGLISH);

	@Inject
	private Client client;

	/**
	 * Reads join dates from the Clan Settings &gt; Members interface.
	 * Uses the same widget indexing approach as the Clanmate Export plugin.
	 *
	 * @return map of normalized username to ISO join date (yyyy-MM-dd)
	 */
	public Map<String, String> scrapeJoinDatesByUsername()
	{
		Map<String, String> joinDates = new HashMap<>();

		ClanSettings clanSettings = client.getClanSettings();
		if (clanSettings == null)
		{
			return joinDates;
		}

		int joinedColumnId = resolveJoinedColumnId();
		scrapeFromMemberListWidgets(joinDates, clanSettings, joinedColumnId);

		if (joinDates.isEmpty() && joinedColumnId != FIRST_COLUMN)
		{
			scrapeFromMemberListWidgets(joinDates, clanSettings, FIRST_COLUMN);
		}

		for (ClanMember clanMember : clanSettings.getMembers())
		{
			if (clanMember.getName().startsWith("[#"))
			{
				continue;
			}

			String key = normalizeUsername(Text.toJagexName(clanMember.getName()));
			if (joinDates.containsKey(key))
			{
				continue;
			}

			LocalDate joinDate = clanMember.getJoinDate();
			if (joinDate != null)
			{
				joinDates.put(key, joinDate.toString());
			}
		}

		log.debug("Scraped {} clan join dates from members interface", joinDates.size());
		return joinDates;
	}

	public boolean isMembersInterfaceOpen()
	{
		return getMembersWidget(RSN_COLUMN) != null;
	}

	private void scrapeFromMemberListWidgets(Map<String, String> joinDates, ClanSettings clanSettings, int joinedColumnId)
	{
		Widget namesWidget = getMembersWidget(RSN_COLUMN);
		Widget joinedWidget = getMembersWidget(joinedColumnId);
		if (namesWidget == null || joinedWidget == null)
		{
			return;
		}

		Widget[] nameChildren = namesWidget.getChildren();
		Widget[] joinedChildren = joinedWidget.getChildren();
		if (nameChildren == null || joinedChildren == null)
		{
			return;
		}

		int clanMemberCount = clanSettings.getMembers().size();
		int lastSuccessfulRsnIndex = 0;
		int otherColumnsPositions = 0;

		for (int i = 0; i < nameChildren.length; i++)
		{
			int rsnIndex = i == 0 ? 1 : lastSuccessfulRsnIndex + 3;
			if (rsnIndex < 0 || rsnIndex >= nameChildren.length)
			{
				continue;
			}

			int joinedIndex = otherColumnsPositions + clanMemberCount;
			if (joinedIndex < 0 || joinedIndex >= joinedChildren.length)
			{
				continue;
			}

			Widget nameWidget = nameChildren[rsnIndex];
			Widget joinedWidgetChild = joinedChildren[joinedIndex];
			if (nameWidget == null || joinedWidgetChild == null)
			{
				continue;
			}

			String rsn = Text.removeTags(nameWidget.getText());
			String joinedText = Text.removeTags(joinedWidgetChild.getText());
			String isoDate = toIsoDate(joinedText);

			if (rsn != null && !rsn.isBlank() && isoDate != null)
			{
				joinDates.put(normalizeUsername(rsn), isoDate);
			}

			lastSuccessfulRsnIndex = rsnIndex;
			otherColumnsPositions++;
		}
	}

	private Widget getMembersWidget(int childId)
	{
		Widget widget = client.getWidget(InterfaceID.CLANS_MEMBERS, childId);
		if (widget != null)
		{
			return widget;
		}

		return client.getWidget((InterfaceID.CLANS_MEMBERS << 16) | childId);
	}

	private int resolveJoinedColumnId()
	{
		String firstHeader = readDropdownHeader(FIRST_DROPDOWN);
		String secondHeader = readDropdownHeader(SECOND_DROPDOWN);

		if (isJoinedHeader(secondHeader))
		{
			return SECOND_COLUMN;
		}

		if (isJoinedHeader(firstHeader))
		{
			return FIRST_COLUMN;
		}

		return SECOND_COLUMN;
	}

	private String readDropdownHeader(int dropdownChildId)
	{
		Widget dropdown = getMembersWidget(dropdownChildId);
		if (dropdown == null)
		{
			return null;
		}

		Widget[] children = dropdown.getChildren();
		if (children == null || children.length <= 4)
		{
			return null;
		}

		return Text.removeTags(children[4].getText());
	}

	private static boolean isJoinedHeader(String header)
	{
		return header != null && header.trim().equalsIgnoreCase("Joined");
	}

	static String normalizeUsername(String name)
	{
		return Text.toJagexName(name).replace(' ', '_').toLowerCase(Locale.ENGLISH);
	}

	static String toIsoDate(String uiDate)
	{
		if (uiDate == null || uiDate.isBlank())
		{
			return null;
		}

		String trimmed = uiDate.trim();
		if (trimmed.equalsIgnoreCase("Not available"))
		{
			return null;
		}

		try
		{
			return LocalDate.parse(trimmed, UI_DATE_SHORT).toString();
		}
		catch (DateTimeParseException ex)
		{
			try
			{
				return LocalDate.parse(trimmed, UI_DATE_LONG).toString();
			}
			catch (DateTimeParseException ignored)
			{
				return null;
			}
		}
	}
}

package com.llamaclub.clan;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanMember;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.clan.ClanTitle;
import net.runelite.client.util.Text;

@Singleton
public class ClanMemberCollector
{
	@Inject
	private Client client;

	@Inject
	private ClanJoinDateScraper joinDateScraper;

	@Getter
	private int lastCollectedMemberCount;

	@Getter
	private int lastCollectedJoinDateCount;

	public Map<String, Object> collect()
	{
		ClanSettings clanSettings = client.getClanSettings();
		if (clanSettings == null)
		{
			return null;
		}

		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return null;
		}

		List<Map<String, Object>> members = new ArrayList<>();
		Map<String, String> scrapedJoinDates = joinDateScraper.scrapeJoinDatesByUsername();
		int joinDateCount = 0;

		for (ClanMember clanMember : clanSettings.getMembers())
		{
			if (clanMember.getName().startsWith("[#"))
			{
				continue;
			}

			String username = Text.toJagexName(clanMember.getName());
			ClanTitle title = clanSettings.titleForRank(clanMember.getRank());
			String rank = title == null ? "Member" : title.getName();
			String rankKey = title == null ? "member" : title.getName().toLowerCase().replaceAll("[-\\s]", "_");
			int rankIndex = clanMember.getRank().getRank();

			Map<String, Object> member = new HashMap<>();
			member.put("username", username);
			member.put("rank", rank);
			member.put("rankKey", rankKey);
			member.put("rankIndex", rankIndex);

			LocalDate joinDate = clanMember.getJoinDate();
			String normalizedUsername = ClanJoinDateScraper.normalizeUsername(username);
			String joinDateIso = scrapedJoinDates.get(normalizedUsername);

			if (joinDateIso == null && joinDate != null)
			{
				joinDateIso = joinDate.toString();
			}

			if (joinDateIso != null)
			{
				member.put("joinDate", joinDateIso);
				joinDateCount++;
			}

			members.add(member);
		}

		lastCollectedMemberCount = members.size();
		lastCollectedJoinDateCount = joinDateCount;

		if (members.isEmpty())
		{
			return null;
		}

		ClanMember self = clanSettings.findMember(local.getName());
		if (self == null)
		{
			self = clanSettings.findMember(Text.toJagexName(local.getName()));
		}

		ClanTitle selfTitle = self != null ? clanSettings.titleForRank(self.getRank()) : null;
		String syncedByRank = selfTitle == null ? "Member" : selfTitle.getName();
		String syncedByRankKey = selfTitle == null ? "member" : selfTitle.getName().toLowerCase().replaceAll("[-\\s]", "_");

		Map<String, Object> syncedBy = new HashMap<>();
		syncedBy.put("username", Text.toJagexName(local.getName()));
		syncedBy.put("rank", syncedByRank);
		syncedBy.put("rankKey", syncedByRankKey);

		Map<String, Object> clanSync = new HashMap<>();
		clanSync.put("clanName", clanSettings.getName());
		clanSync.put("clanSize", members.size());
		clanSync.put("syncedBy", syncedBy);
		clanSync.put("members", members);
		return clanSync;
	}

	public String describeJoinDateReadiness()
	{
		if (!joinDateScraper.isMembersInterfaceOpen())
		{
			return "Open Clan Settings and go to the Members tab before syncing.";
		}

		return "Could not read join dates. On the Members tab, set the right column to Joined, then sync again.";
	}
}

