package com.llamaclub.collection;

import net.runelite.api.Client;
import net.runelite.api.StructComposition;

public enum CollectionLogRank
{
	NONE(0),
	BRONZE(1714),
	IRON(1715),
	STEEL(1716),
	BLACK(1717),
	MITHRIL(1718),
	ADAMANT(1719),
	RUNE(1740),
	DRAGON(1741),
	GILDED(1742);

	private static final int THRESHOLD_PARAM = 2232;

	private final int structId;

	CollectionLogRank(int structId)
	{
		this.structId = structId;
	}

	public String getDisplayName()
	{
		if (this == NONE)
		{
			return "None";
		}
		return name().charAt(0) + name().substring(1).toLowerCase();
	}

	public int getClogRankThreshold(Client client, int collectionCountMax)
	{
		switch (this)
		{
			case NONE:
				return 0;

			case GILDED:
				return 25 * (int) (0.9 * collectionCountMax / 25);

			default:
				StructComposition struct = client.getStructComposition(structId);
				if (struct == null)
				{
					throw new IllegalStateException("Missing struct for rank " + name());
				}
				return struct.getIntValue(THRESHOLD_PARAM);
		}
	}
}

package com.llamaclub.combat;

import java.time.Duration;
import java.util.HashSet;
import java.util.Set;
import com.llamaclub.LlamaClubConfig;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Hitsplat;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

@Slf4j
@Singleton
public class BarrowsBrotherCombatTracker
{
	static final int BROTHER_COUNT = 6;

	private static final Set<String> BROTHER_NAMES = Set.of(
		"Dharok the Wretched",
		"Ahrim the Blighted",
		"Verac the Defiled",
		"Torag the Corrupted",
		"Karil the Tainted",
		"Guthan the Infested"
	);

	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	@Inject
	private LlamaClubConfig config;

	private final RunState state = new RunState();

	static boolean isBarrowsBrotherName(String name)
	{
		return name != null && BROTHER_NAMES.contains(name);
	}

	static boolean isBarrowsBrother(NPC npc)
	{
		return npc != null && isBarrowsBrotherName(npc.getName());
	}

	public int getBrotherKillCount()
	{
		return state.killedBrothers.size();
	}

	public long getTotalTimeMillis()
	{
		return state.totalTimeMillis;
	}

	public Duration getTotalDuration()
	{
		return Duration.ofMillis(state.totalTimeMillis);
	}

	public boolean hasCompleteRun()
	{
		return state.killedBrothers.size() == BROTHER_COUNT;
	}

	public boolean canTrackBrother(String brotherName)
	{
		if (brotherName == null || state.killedBrothers.contains(brotherName))
		{
			return false;
		}

		return state.activeBrotherName == null || state.activeBrotherName.equals(brotherName);
	}

	public void ensureTracking(String brotherName, long nowMillis)
	{
		beginFightOnFirstHit(state, brotherName, nowMillis);
	}

	public void recordSpecAttempt()
	{
		state.stats.incrementSpecialAttacks();
	}

	public void recordSpecHit(String weaponName, int damage)
	{
		state.stats.addSpecHit(weaponName, damage);
	}

	/**
	 * Returns aggregated run data when all six brothers were tracked, otherwise null.
	 */
	public CompletedFight consumeCompletedRun()
	{
		if (!hasCompleteRun())
		{
			log.info(
				"Barrows chest opened with incomplete run tracking ({}/{} brothers, {}ms timed)",
				state.killedBrothers.size(),
				BROTHER_COUNT,
				state.totalTimeMillis
			);
			return null;
		}

		FightCombatStats statsSnapshot = new FightCombatStats();
		statsSnapshot.mergeFrom(state.stats);

		CompletedFight completed = new CompletedFight(
			BossNpcRegistry.BARROWS_CHESTS,
			getTotalDuration(),
			statsSnapshot,
			System.currentTimeMillis()
		);

		log.info(
			"Barrows run complete: {}ms, {} damage, {} hits, {} specs",
			state.totalTimeMillis,
			state.stats.getTotalDamage(),
			state.stats.getHitCount(),
			state.stats.getSpecialAttacks()
		);

		reset();
		return completed;
	}

	public void reset()
	{
		state.reset();
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		if (!config.notifyKillCount())
		{
			return;
		}

		Actor source = event.getSource();
		Actor target = event.getTarget();
		NPC brother = null;

		if (source == client.getLocalPlayer() && target instanceof NPC)
		{
			brother = (NPC) target;
		}
		else if (target == client.getLocalPlayer() && source instanceof NPC)
		{
			brother = (NPC) source;
		}

		if (!isBarrowsBrother(brother))
		{
			return;
		}

		tryStartFight(brother.getName());
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (!config.notifyKillCount())
		{
			return;
		}

		if (!(event.getActor() instanceof NPC))
		{
			return;
		}

		Hitsplat hitsplat = event.getHitsplat();
		if (!hitsplat.isMine())
		{
			return;
		}

		NPC npc = (NPC) event.getActor();
		if (!isBarrowsBrother(npc))
		{
			return;
		}

		String brotherName = npc.getName();
		if (!canTrackBrother(brotherName))
		{
			return;
		}

		tryStartFight(brotherName);
		state.stats.addHit(getEquippedWeaponName(), hitsplat.getAmount());
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (!config.notifyKillCount())
		{
			return;
		}

		if (!(event.getActor() instanceof NPC))
		{
			return;
		}

		NPC npc = (NPC) event.getActor();
		if (!isBarrowsBrother(npc))
		{
			return;
		}

		recordBrotherKill(state, npc.getName(), System.currentTimeMillis());
	}

	private void tryStartFight(String brotherName)
	{
		if (!canTrackBrother(brotherName))
		{
			return;
		}

		beginFightOnFirstHit(state, brotherName, System.currentTimeMillis());
	}

	static void beginFightOnFirstHit(RunState state, String brotherName, long nowMillis)
	{
		if (brotherName == null || state.killedBrothers.contains(brotherName))
		{
			return;
		}

		if (state.killedBrothers.size() >= BROTHER_COUNT)
		{
			return;
		}

		if (brotherName.equals(state.activeBrotherName) && state.fightStartMillis > 0)
		{
			return;
		}

		if (state.activeBrotherName != null && !state.activeBrotherName.equals(brotherName))
		{
			return;
		}

		state.fightStartMillis = nowMillis;
		state.activeBrotherName = brotherName;
	}

	static boolean recordBrotherKill(RunState state, String brotherName, long nowMillis)
	{
		if (brotherName == null || state.killedBrothers.contains(brotherName))
		{
			return false;
		}

		if (state.killedBrothers.size() >= BROTHER_COUNT)
		{
			return false;
		}

		if (state.activeBrotherName == null)
		{
			log.debug("Barrows brother {} died without a tracked fight start", brotherName);
			return false;
		}

		if (!state.activeBrotherName.equals(brotherName))
		{
			log.debug(
				"Barrows brother death ignored due to name mismatch (active={}, dead={})",
				state.activeBrotherName,
				brotherName
			);
			return false;
		}

		long durationMillis = Math.max(0L, nowMillis - state.fightStartMillis);
		state.totalTimeMillis += durationMillis;
		state.killedBrothers.add(brotherName);
		state.fightStartMillis = 0;
		state.activeBrotherName = null;

		log.debug(
			"Barrows brother {} killed in {}ms (run total {}ms, {}/{} brothers)",
			brotherName,
			durationMillis,
			state.totalTimeMillis,
			state.killedBrothers.size(),
			BROTHER_COUNT
		);
		return true;
	}

	private String getEquippedWeaponName()
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment == null)
		{
			return "Unarmed";
		}

		Item weapon = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		if (weapon == null)
		{
			return "Unarmed";
		}

		return itemManager.getItemComposition(weapon.getId()).getName();
	}

	static final class RunState
	{
		long fightStartMillis;
		String activeBrotherName;
		final Set<String> killedBrothers = new HashSet<>();
		long totalTimeMillis;
		final FightCombatStats stats = new FightCombatStats();

		void reset()
		{
			fightStartMillis = 0;
			activeBrotherName = null;
			killedBrothers.clear();
			totalTimeMillis = 0;
			stats.clear();
		}
	}
}

package com.llamaclub.combat;

import com.llamaclub.LlamaClubConfig;
import java.time.Duration;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Hitsplat;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

@Slf4j
@Singleton
public class BossFightTracker
{
	private static final long PENDING_TTL_MILLIS = 60_000L;
	private static final long RUN_IDLE_TTL_MILLIS = 60_000L;

	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	@Inject
	private LlamaClubConfig config;

	private final Map<String, BossRunState> activeRuns = new HashMap<>();
	private final Map<String, CompletedFight> pendingByBossKey = new HashMap<>();

	public boolean isTrackingBossNpc(int npcIndex, String bossKey)
	{
		BossRunState run = activeRuns.get(bossKey);
		if (run == null)
		{
			return false;
		}

		return run.activeNpcIndex < 0 || run.activeNpcIndex == npcIndex;
	}

	public void ensureTracking(String bossKey, int npcIndex, long nowMillis)
	{
		BossRunState run = activeRuns.computeIfAbsent(bossKey, BossRunState::new);
		run.activeNpcIndex = npcIndex;
		run.lastActivityMillis = nowMillis;
		if (run.segmentStartMillis <= 0)
		{
			run.segmentStartMillis = nowMillis;
		}
	}

	public void recordSpecAttempt(String bossKey)
	{
		BossRunState run = activeRuns.get(bossKey);
		if (run != null)
		{
			run.stats.incrementSpecialAttacks();
			run.lastActivityMillis = System.currentTimeMillis();
		}
	}

	public void recordSpecHit(String bossKey, String weaponName, int damage)
	{
		BossRunState run = activeRuns.get(bossKey);
		if (run != null)
		{
			run.stats.addSpecHit(weaponName, damage);
			run.lastActivityMillis = System.currentTimeMillis();
		}
	}

	public boolean hasPendingFight(String bossKey)
	{
		CompletedFight pending = pendingByBossKey.get(bossKey);
		return pending != null && !isExpired(pending.getCompletedAtMillis());
	}

	public Duration peekPendingDuration(String bossKey)
	{
		CompletedFight pending = pendingByBossKey.get(bossKey);
		if (pending == null || isExpired(pending.getCompletedAtMillis()))
		{
			return null;
		}

		return pending.getDuration();
	}

	public CompletedFight consume(String bossKey)
	{
		CompletedFight pending = pendingByBossKey.remove(bossKey);
		if (pending == null || isExpired(pending.getCompletedAtMillis()))
		{
			return null;
		}

		return pending;
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (!isEnabled())
		{
			return;
		}

		Hitsplat hitsplat = event.getHitsplat();
		if (!hitsplat.isMine() || !(event.getActor() instanceof NPC))
		{
			return;
		}

		NPC npc = (NPC) event.getActor();
		String bossKey = BossNpcRegistry.resolveBossKey(npc);
		if (!BossNpcRegistry.isTrackableBossKey(bossKey))
		{
			return;
		}

		long now = System.currentTimeMillis();
		BossRunState run = activeRuns.computeIfAbsent(bossKey, key -> new BossRunState(key));
		if (run.segmentStartMillis <= 0)
		{
			run.segmentStartMillis = now;
		}

		run.activeNpcIndex = npc.getIndex();
		run.lastActivityMillis = now;

		String weaponName = getEquippedWeaponName();
		run.stats.addHit(weaponName, hitsplat.getAmount());
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (!isEnabled() || !(event.getActor() instanceof NPC))
		{
			return;
		}

		NPC npc = (NPC) event.getActor();
		String bossKey = BossNpcRegistry.resolveBossKey(npc);
		if (!BossNpcRegistry.isTrackableBossKey(bossKey))
		{
			return;
		}

		BossRunState run = activeRuns.get(bossKey);
		if (run == null || run.segmentStartMillis <= 0)
		{
			return;
		}

		long now = System.currentTimeMillis();
		run.totalDurationMillis += Math.max(0L, now - run.segmentStartMillis);
		run.segmentStartMillis = 0;
		run.activeNpcIndex = -1;
		run.lastActivityMillis = now;

		if (BossNpcRegistry.isMultiPhaseBoss(bossKey) && !BossNpcRegistry.isTerminalNpc(bossKey, npc.getId()))
		{
			log.debug("Boss {} phase death recorded, waiting for terminal phase", bossKey);
			return;
		}

		finalizeRun(bossKey, run, now);
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!isEnabled())
		{
			return;
		}

		long now = System.currentTimeMillis();
		expirePending(now);
		expireIdleRuns(now);
	}

	private void finalizeRun(String bossKey, BossRunState run, long nowMillis)
	{
		if (!run.stats.hasCombatData() && run.totalDurationMillis <= 0)
		{
			activeRuns.remove(bossKey);
			return;
		}

		Duration duration = Duration.ofMillis(Math.max(0L, run.totalDurationMillis));
		CompletedFight completed = new CompletedFight(bossKey, duration, run.stats, nowMillis);
		pendingByBossKey.put(bossKey, completed);
		activeRuns.remove(bossKey);

		log.debug(
			"Completed fight for {} in {}ms with {} damage",
			bossKey,
			run.totalDurationMillis,
			run.stats.getTotalDamage()
		);
	}

	private void expirePending(long nowMillis)
	{
		Iterator<Map.Entry<String, CompletedFight>> iterator = pendingByBossKey.entrySet().iterator();
		while (iterator.hasNext())
		{
			Map.Entry<String, CompletedFight> entry = iterator.next();
			if (isExpired(entry.getValue().getCompletedAtMillis(), nowMillis))
			{
				iterator.remove();
			}
		}
	}

	private void expireIdleRuns(long nowMillis)
	{
		Iterator<Map.Entry<String, BossRunState>> iterator = activeRuns.entrySet().iterator();
		while (iterator.hasNext())
		{
			BossRunState run = iterator.next().getValue();
			if (nowMillis - run.lastActivityMillis > RUN_IDLE_TTL_MILLIS)
			{
				finalizeRun(run.bossKey, run, nowMillis);
			}
		}
	}

	private String getEquippedWeaponName()
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment == null)
		{
			return "Unarmed";
		}

		Item weapon = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		if (weapon == null)
		{
			return "Unarmed";
		}

		return itemManager.getItemComposition(weapon.getId()).getName();
	}

	private boolean isEnabled()
	{
		return config.notifyKillCount();
	}

	private static boolean isExpired(long completedAtMillis)
	{
		return isExpired(completedAtMillis, System.currentTimeMillis());
	}

	private static boolean isExpired(long completedAtMillis, long nowMillis)
	{
		return nowMillis - completedAtMillis > PENDING_TTL_MILLIS;
	}

	public void reset()
	{
		activeRuns.clear();
		pendingByBossKey.clear();
	}

	static final class BossRunState
	{
		final String bossKey;
		final FightCombatStats stats = new FightCombatStats();
		long segmentStartMillis;
		long totalDurationMillis;
		long lastActivityMillis;
		int activeNpcIndex = -1;

		BossRunState(String bossKey)
		{
			this.bossKey = bossKey;
			this.lastActivityMillis = System.currentTimeMillis();
		}
	}

	static void applyHit(BossRunState run, String weaponName, int damage, long nowMillis)
	{
		if (run.segmentStartMillis <= 0)
		{
			run.segmentStartMillis = nowMillis;
		}

		run.lastActivityMillis = nowMillis;
		run.stats.addHit(weaponName, damage);
	}

	static CompletedFight finalizeRunState(BossRunState run, long nowMillis)
	{
		if (run.segmentStartMillis > 0)
		{
			run.totalDurationMillis += Math.max(0L, nowMillis - run.segmentStartMillis);
			run.segmentStartMillis = 0;
		}

		Duration duration = Duration.ofMillis(Math.max(0L, run.totalDurationMillis));
		return new CompletedFight(run.bossKey, duration, run.stats, nowMillis);
	}
}

