package com.llamaclub.pet;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

public final class PetItems
{
	private static final Set<String> PET_NAMES = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		"abyssal orphan", "baby mole", "baron", "bran", "butch", "callisto cub", "dom", "gull",
		"hellpuppy", "huberte", "ikkle hydra", "jal-nib-rek", "kalphite princess", "lil' zik",
		"lil'viathan", "little nightmare", "moxi", "muphin", "nexling", "nid", "noon", "olmlet",
		"pet chaos elemental", "pet dagannoth prime", "pet dagannoth rex", "pet dagannoth supreme",
		"pet dark core", "pet general graardor", "pet k'ril tsutsaroth", "pet kraken", "pet kree'arra",
		"pet smoke devil", "pet snakeling", "pet zilyana", "phoenix", "prince black dragon",
		"scorpia's offspring", "scurry", "skotos", "smolcano", "smol heredit", "sraracha",
		"tiny tempor", "tumeken's guardian", "tzrek-jad", "venenatis spiderling", "vet'ion jr.",
		"vorki", "wisp", "yami", "youngllef",
		"baby chinchompa", "beaver", "giant squirrel", "heron", "rift guardian", "rock golem",
		"rocky", "soup", "tangleroot",
		"abyssal protector", "bloodhound", "chompy chick", "herbi", "lil' creator",
		"pet penance queen", "quetzin"
	)));

	private PetItems()
	{
	}

	public static boolean isPet(String itemName)
	{
		if (itemName == null || itemName.isEmpty())
		{
			return false;
		}

		String normalized = itemName.toLowerCase().trim();
		if (PET_NAMES.contains(normalized))
		{
			return true;
		}

		if (normalized.startsWith("pet "))
		{
			String withoutPrefix = normalized.substring(4).trim();
			return PET_NAMES.contains(withoutPrefix) || PET_NAMES.contains(normalized);
		}

		return normalized.contains("pet ");
	}
}

package com.llamaclub.service;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
public class BingoLootWhitelistService
{
	private final Gson gson;

	private volatile Set<String> cachedNames = Set.of();

	@Inject
	BingoLootWhitelistService(Gson gson)
	{
		this.gson = gson;
	}

	public Set<String> asSet()
	{
		return cachedNames;
	}

	public void updateFromResponseBody(String responseBody)
	{
		List<String> names = parseNamesFromResponse(responseBody);
		if (names == null)
		{
			return;
		}

		update(names);
	}

	public void update(List<String> names)
	{
		if (names == null || names.isEmpty())
		{
			cachedNames = Set.of();
			return;
		}

		Set<String> merged = names.stream()
			.filter(name -> name != null && !name.isBlank())
			.map(String::trim)
			.map(String::toLowerCase)
			.collect(Collectors.toCollection(HashSet::new));
		cachedNames = Collections.unmodifiableSet(merged);
	}

	@SuppressWarnings("unchecked")
	private List<String> parseNamesFromResponse(String responseBody)
	{
		if (responseBody == null || responseBody.isBlank())
		{
			return null;
		}

		try
		{
			Map<String, Object> parsed = gson.fromJson(
				responseBody,
				new TypeToken<Map<String, Object>>() {}.getType()
			);

			Object whitelist = parsed.get("bingoLootWhitelist");
			if (!(whitelist instanceof List))
			{
				return null;
			}

			return ((List<?>) whitelist).stream()
				.filter(String.class::isInstance)
				.map(String.class::cast)
				.collect(Collectors.toList());
		}
		catch (RuntimeException ignored)
		{
			return null;
		}
	}
}

package com.llamaclub.service;

import com.llamaclub.LlamaClubConfig;
import com.llamaclub.api.PayloadBuilder;
import com.llamaclub.api.WebhookClient;
import com.llamaclub.clan.ClanMemberCollector;
import java.util.List;
import java.util.Map;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;

@Singleton
@Slf4j
public class ClanSyncService
{
	@Inject
	private LlamaClubConfig config;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClanMemberCollector clanMemberCollector;

	@Inject
	private PayloadBuilder payloadBuilder;

	@Inject
	private WebhookClient webhookClient;

	public void syncNow(Consumer<Boolean> callback)
	{
		syncNow((success, error) ->
		{
			if (callback != null)
			{
				callback.accept(success);
			}
		});
	}

	public void syncNow(BiConsumer<Boolean, String> callback)
	{
		if (!config.webhookEnabled() || config.pluginToken() == null || config.pluginToken().isBlank())
		{
			if (callback != null)
			{
				callback.accept(false, null);
			}
			return;
		}

		if (client.getGameState() != GameState.LOGGED_IN)
		{
			if (callback != null)
			{
				callback.accept(false, "Log into OSRS before syncing clan members");
			}
			return;
		}

		clientThread.invokeLater(() ->
		{
			Map<String, Object> clanSync = clanMemberCollector.collect();
			if (clanSync == null)
			{
				if (callback != null)
				{
					callback.accept(false, "Open your clan chat and ensure you are a member before syncing");
				}
				return;
			}

			if (countMembersWithJoinDate(clanSync) == 0)
			{
				log.warn(
					"Clan sync aborted: no join dates collected for {} members",
					clanMemberCollector.getLastCollectedMemberCount()
				);

				if (callback != null)
				{
					callback.accept(false, clanMemberCollector.describeJoinDateReadiness());
				}
				return;
			}

			log.info(
				"Clan sync sending {} members with {} join dates",
				clanMemberCollector.getLastCollectedMemberCount(),
				clanMemberCollector.getLastCollectedJoinDateCount()
			);

			Map<String, Object> payload = payloadBuilder.buildClanSync(clanSync);
			webhookClient.sendAsync(config.webhookUrl(), payload, callback);
		});
	}

	public int getLastCollectedJoinDateCount()
	{
		return clanMemberCollector.getLastCollectedJoinDateCount();
	}

	public int getLastCollectedMemberCount()
	{
		return clanMemberCollector.getLastCollectedMemberCount();
	}

	private static int countMembersWithJoinDate(Map<String, Object> clanSync)
	{
		Object membersObj = clanSync.get("members");
		if (!(membersObj instanceof List))
		{
			return 0;
		}

		int count = 0;
		for (Object memberObj : (List<?>) membersObj)
		{
			if (memberObj instanceof Map && ((Map<?, ?>) memberObj).containsKey("joinDate"))
			{
				count++;
			}
		}

		return count;
	}
}

package com.llamaclub.service;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
public class PluginFilterSettingsService
{
	public static final int DEFAULT_LOOT_MIN_VALUE = 1_000_000;
	public static final int DEFAULT_CLUE_MIN_VALUE = 0;
	public static final int DEFAULT_CLUE_SCREENSHOT_MIN_VALUE = 0;

	private volatile int lootMinValue = DEFAULT_LOOT_MIN_VALUE;
	private volatile int clueMinValue = DEFAULT_CLUE_MIN_VALUE;
	private volatile int clueScreenshotMinValue = DEFAULT_CLUE_SCREENSHOT_MIN_VALUE;

	private final Gson gson;

	@Inject
	PluginFilterSettingsService(Gson gson)
	{
		this.gson = gson;
	}

	public int lootMinValue()
	{
		return lootMinValue;
	}

	public int clueMinValue()
	{
		return clueMinValue;
	}

	public int clueScreenshotMinValue()
	{
		return clueScreenshotMinValue;
	}

	public void updateFromResponseBody(String responseBody)
	{
		Map<String, Object> settings = parseSettingsFromResponse(responseBody);
		if (settings == null)
		{
			return;
		}

		update(settings);
	}

	public void update(Map<String, Object> settings)
	{
		if (settings == null)
		{
			return;
		}

		Integer loot = parseInt(settings.get("lootMinValue"));
		if (loot != null && loot >= 0)
		{
			lootMinValue = loot;
		}

		Integer clue = parseInt(settings.get("clueMinValue"));
		if (clue != null && clue >= 0)
		{
			clueMinValue = clue;
		}

		Integer screenshot = parseInt(settings.get("clueScreenshotMinValue"));
		if (screenshot != null && screenshot >= 0)
		{
			clueScreenshotMinValue = screenshot;
		}
	}

	@SuppressWarnings("unchecked")
	private Map<String, Object> parseSettingsFromResponse(String responseBody)
	{
		if (responseBody == null || responseBody.isBlank())
		{
			return null;
		}

		try
		{
			Map<String, Object> parsed = gson.fromJson(
				responseBody,
				new TypeToken<Map<String, Object>>() {}.getType()
			);

			Object settings = parsed.get("pluginFilterSettings");
			if (!(settings instanceof Map))
			{
				return null;
			}

			return (Map<String, Object>) settings;
		}
		catch (RuntimeException ignored)
		{
			return null;
		}
	}

	private static Integer parseInt(Object value)
	{
		if (value instanceof Number)
		{
			return ((Number) value).intValue();
		}

		if (value instanceof String)
		{
			try
			{
				return Integer.parseInt((String) value);
			}
			catch (NumberFormatException ignored)
			{
				return null;
			}
		}

		return null;
	}
}

package com.llamaclub.service;

import com.llamaclub.LlamaClubConfig;
import com.llamaclub.api.PayloadBuilder;
import com.llamaclub.api.WebhookClient;
import com.llamaclub.sync.PlayerDataCollector;
import java.util.Map;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;

@Singleton
public class SyncService
{
	@Inject
	private LlamaClubConfig config;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private PlayerDataCollector playerDataCollector;

	@Inject
	private PayloadBuilder payloadBuilder;

	@Inject
	private WebhookClient webhookClient;

	public void syncNow(Consumer<Boolean> callback)
	{
		syncNow((success, error) ->
		{
			if (callback != null)
			{
				callback.accept(success);
			}
		});
	}

	public void syncOnSessionEnd(Consumer<Boolean> callback)
	{
		runSync(callback == null ? null : (success, error) -> callback.accept(success), true, true);
	}

	public void syncNow(BiConsumer<Boolean, String> callback)
	{
		runSync(callback, false, false);
	}

	public void syncBlocking(Consumer<Boolean> callback)
	{
		runSync(callback == null ? null : (success, error) ->
		{
			if (callback != null)
			{
				callback.accept(success);
			}
		}, true, false);
	}

	private void runSync(BiConsumer<Boolean, String> callback, boolean blocking, boolean sessionEnd)
	{
		if (!config.webhookEnabled() || config.pluginToken() == null || config.pluginToken().isBlank())
		{
			if (callback != null)
			{
				callback.accept(false, null);
			}
			return;
		}

		if (!sessionEnd && client.getGameState() != GameState.LOGGED_IN)
		{
			if (callback != null)
			{
				callback.accept(false, "Log into OSRS before syncing");
			}
			return;
		}

		Runnable syncTask = () ->
		{
			Map<String, Object> playerSync = playerDataCollector.collectAll();
			Map<String, Object> payload = payloadBuilder.buildPlayerSync(playerSync);
			webhookClient.sendAsync(config.webhookUrl(), payload, callback);
		};

		if (blocking)
		{
			clientThread.invoke(syncTask);
		}
		else
		{
			clientThread.invokeLater(syncTask);
		}
	}
}

package com.llamaclub.sync;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
public class BossKillCountSync
{
	@Inject
	private ConfigManager configManager;

	@Inject
	private CombatAchievementBossStatsReader combatAchievementBossStatsReader;

	public Map<String, Object> sync()
	{
		Map<String, Map<String, Object>> merged = new HashMap<>();
		String profile = configManager.getRSProfileKey();

		List<String> killCountKeys = configManager.getRSProfileConfigurationKeys("killcount", profile, "");
		if (killCountKeys != null)
		{
			for (String key : killCountKeys)
			{
				Integer killCount = configManager.getRSProfileConfiguration("killcount", key, int.class);
				if (killCount == null || killCount <= 0)
				{
					continue;
				}

				Double personalBestSeconds = configManager.getRSProfileConfiguration("personalbest", key, double.class);
				mergeBoss(merged, key, killCount, personalBestSeconds, "runelite_profile_config");
			}
		}

		mergePersonalBestOnlyBosses(merged, profile);

		try
		{
			for (CombatAchievementBossStat caStat : combatAchievementBossStatsReader.readAll().values())
			{
				String key = CombatAchievementBossStatsReader.bossKey(caStat.getName());
				mergeBoss(merged, key, caStat.getKillCount(), caStat.getPersonalBestSeconds(), "combat_achievements");
			}
		}
		catch (RuntimeException ex)
		{
			// Keep profile-config boss data even if CA enrichment fails.
		}

		List<Map<String, Object>> bosses = new ArrayList<>(merged.values());
		bosses.sort(Comparator.comparing(b -> String.valueOf(b.get("name"))));

		Map<String, Object> result = new HashMap<>();
		result.put("bosses", bosses);
		result.put("bossCount", bosses.size());
		result.put("source", "merged");
		return result;
	}

	/**
	 * Tiered Lunar Chest PBs (e.g. {@code lunar chest 1}) live only under {@code personalbest},
	 * not {@code killcount}. Include them so the website speed leaderboard can merge tiers.
	 */
	private void mergePersonalBestOnlyBosses(Map<String, Map<String, Object>> merged, String profile)
	{
		List<String> personalBestKeys = configManager.getRSProfileConfigurationKeys("personalbest", profile, "");
		if (personalBestKeys == null)
		{
			return;
		}

		for (String key : personalBestKeys)
		{
			if (merged.containsKey(key))
			{
				continue;
			}

			Double personalBestSeconds = configManager.getRSProfileConfiguration("personalbest", key, double.class);
			if (personalBestSeconds == null || personalBestSeconds <= 0)
			{
				continue;
			}

			mergeBoss(merged, key, null, personalBestSeconds, "runelite_profile_config");
		}
	}

	private static void mergeBoss(
		Map<String, Map<String, Object>> merged,
		String key,
		Integer killCount,
		Double personalBestSeconds,
		String source
	)
	{
		Map<String, Object> boss = merged.computeIfAbsent(key, ignored -> new HashMap<>());
		boss.put("name", CombatAchievementBossStatsReader.displayName(key));

		if (killCount != null && killCount > 0)
		{
			int existingKc = 0;
			if (boss.containsKey("killCount"))
			{
				Object existing = boss.get("killCount");
				if (existing instanceof Number)
				{
					existingKc = ((Number) existing).intValue();
				}
			}

			if (killCount >= existingKc)
			{
				boss.put("killCount", killCount);
			}
		}

		if (personalBestSeconds != null && personalBestSeconds > 0)
		{
			Double existingPb = null;
			if (boss.containsKey("personalBestSeconds"))
			{
				Object existing = boss.get("personalBestSeconds");
				if (existing instanceof Number)
				{
					existingPb = ((Number) existing).doubleValue();
				}
			}

			if ("combat_achievements".equals(source) || existingPb == null || personalBestSeconds < existingPb)
			{
				boss.put("personalBestSeconds", personalBestSeconds);
				boss.put("personalBest", BossTimeFormat.formatSeconds(personalBestSeconds));
				boss.put("personalBestSource", source);
			}
		}
	}
}

package com.llamaclub.sync;

final class BossTimeFormat
{
	private BossTimeFormat()
	{
	}

	static String formatSeconds(double totalSeconds)
	{
		long hours = (long) (totalSeconds / 3600);
		long minutes = (long) ((totalSeconds % 3600) / 60);
		double seconds = totalSeconds % 60;
		long wholeSeconds = (long) seconds;
		long tenths = Math.round((seconds - wholeSeconds) * 10);

		if (hours > 0)
		{
			return String.format("%d:%02d:%02d.%d", hours, minutes, wholeSeconds, tenths);
		}

		return String.format("%d:%02d.%d", minutes, wholeSeconds, tenths);
	}

	static Double parseTimeString(String time)
	{
		if (time == null)
		{
			return null;
		}

		String trimmed = time.trim().toLowerCase();
		trimmed = trimmed.replace(" ", "");
		trimmed = trimmed.replace('s', ' ');
		trimmed = trimmed.trim();

		if (trimmed.isEmpty())
		{
			return null;
		}

		if (trimmed.contains(":"))
		{
			String[] parts = trimmed.split(":");
			if (parts.length == 2)
			{
				try
				{
					int minutes = Integer.parseInt(parts[0]);
					double seconds = Double.parseDouble(parts[1]);
					return (minutes * 60D) + seconds;
				}
				catch (NumberFormatException ignored)
				{
					return null;
				}
			}

			if (parts.length == 3)
			{
				try
				{
					int hours = Integer.parseInt(parts[0]);
					int minutes = Integer.parseInt(parts[1]);
					double seconds = Double.parseDouble(parts[2]);
					return (hours * 3600D) + (minutes * 60D) + seconds;
				}
				catch (NumberFormatException ignored)
				{
					return null;
				}
			}
		}

		try
		{
			return Double.parseDouble(trimmed);
		}
		catch (NumberFormatException ignored)
		{
			return null;
		}
	}
}

