	public void mapsServerErrorResponsesToActionableText()
	{
		Assert.assertEquals(
			"Website server error during ingest — contact a clan admin",
			WebhookClientErrorMessages.describeFailure(gson, 500, "{\"message\":\"Server Error\"}")
		);
